# Only tests of CRuby's default collector, never allocation comparisons.
exclude(:test_expand_heap, 'default GC expands RVALUE heap pages; Mere uses native store arenas')
exclude(:test_gc_config_disable_major, 'default GC can disable major collections and retain minor collections; Mere always marks the full graph')
exclude(:test_gc_config_full_mark_by_default, 'rgengc_allow_full_mark config belongs to the default generational GC')
exclude(:test_gc_config_setting_returns_updated_config_hash, 'rgengc_allow_full_mark config belongs to the default generational GC')
exclude(:test_gc_config_implementation, 'compares the selected CRuby GC library name; Mere truthfully reports mere-ruby, and the reference must keep its own collector')
exclude(:test_gc_internals, 'requires default GC HEAP_PAGE_OBJ_LIMIT and BASE_SLOT_SIZE, which Mere does not have')
exclude(:test_gc_parameter, 'tests default GC RUBY_GC_HEAP and generational tuning environment variables')
exclude(:test_heaps_grow_independently, 'requires RVALUE size-pool heaps and heap_available_slots')
exclude(:test_latest_gc_info, 'allocates until default GC heap_free_slots plus heap_allocatable_slots are exhausted')
exclude(:test_old_to_young_reference, 'requires old and young generations and the old object dump flag')
exclude(:test_start_immediate_sweep, 'requires a deferred sweep phase; Mere sweeps synchronously')
exclude(:test_stat, 'compares default GC heap_free_slots with ObjectSpace FREE slots')
exclude(:test_stat_constraints, 'asserts RVALUE slot and page accounting identities')
exclude(:test_stat_heap, 'requires numbered RVALUE size pools, slot sizes, and per-heap page counters')
exclude(:test_stat_heap_all, 'requires numbered RVALUE size pools; Mere has no slot heaps')
exclude(:test_stat_heap_constraints, 'compares numbered RVALUE heap page and slot sums against global stats')
exclude(:test_thrashing_for_young_objects, 'requires young generations and default GC page growth counters')
